import { useTranslation } from "@fanfanlo";
import { Box, Alert } from "@mui/material";
import { ScriptEditorContentV2 } from "@src/components/script-editor/content/v2/ScriptEditorContentV2";
import { useRouter } from "next/router";
import { useEffect, useState } from "react";
import { Log } from "@fanfanlo";
import type { DifficultyLevel } from "@src/services/droid-docs-api";

const fileLog = new Log(false, 'ExamplesScriptsContent_f');

interface ScriptParams {
    category?: DifficultyLevel;
    name?: string;
    script: boolean;
}

/**
 * 处理 Deep Link 路由的脚本示例页面
 *
 * Deep Link URL 格式:
 * /examples/scripts?category=beginner&name=vibrate&script=true
 *
 * 参数说明:
 * - category: 脚本难度级别 (beginner, intermediate, advanced) - 可选
 * - name: 脚本名称 - 可选
 * - script: 是否加载脚本内容 (true/false) - 默认 true
 */
export function ExamplesScriptsContent() {
    const router = useRouter();
    const { t } = useTranslation(`homepage/components/page/examples/scripts/content`);

    const [params, setParams] = useState<ScriptParams>({
        script: true
    });

    const [isReady, setIsReady] = useState(false);

    // 从 query 参数提取脚本参数
    useEffect(() => {
        if (!router.isReady) {
            fileLog.log('ExamplesScriptsContent', 'Router not ready yet');
            return;
        }

        fileLog.log('ExamplesScriptsContent', 'Router is ready, processing query params');

        const { category, name, script } = router.query;

        fileLog.log('ExamplesScriptsContent', `Query params: category=${category}, name=${name}, script=${script}`);

        // 解析 script 参数 (可以为字符串 'true'/'false' 或 true/false)
        const scriptBool = script === 'false' ? false : true;
        fileLog.log('ExamplesScriptsContent', `Parsed script param: ${scriptBool}`);

        // 构建参数对象 (category 和 name 可以为空)
        const newParams: ScriptParams = {
            category: category as DifficultyLevel | undefined,
            name: name as string | undefined,
            script: scriptBool
        };

        fileLog.log('ExamplesScriptsContent', `Updated params: ${JSON.stringify(newParams)}`);
        setParams(newParams);
        setIsReady(true);
    }, [router.isReady, router.query]);

    // 如果参数为空，显示提示信息
    if (!isReady) {
        fileLog.log('ExamplesScriptsContent', 'Still loading router');
        return (
            <Box sx={{ p: 2 }}>
                <Alert severity="info">
                    {t('ExamplesScriptsContent.loading', 'Loading...')}
                </Alert>
            </Box>
        );
    }

    // 参数都为空时，显示默认内容（默认为初级第一个脚本）
    if (!params.category && !params.name) {
        fileLog.log('ExamplesScriptsContent', 'No category and name provided, using defaults (beginner first script)');
        return (
            <Box>
                <ScriptEditorContentV2 />
            </Box>
        );
    }

    // 只有 category 或只有 name 时，显示错误信息
    if (!params.category || !params.name) {
        fileLog.log('ExamplesScriptsContent', `Invalid params: category=${params.category}, name=${params.name}`);
        return (
            <Box sx={{ p: 2 }}>
                <Alert severity="error">
                    {t('ExamplesScriptsContent.invalidParams', '无效的脚本参数，请确保 category 和 name 都已提供')}
                </Alert>
            </Box>
        );
    }

    fileLog.log('ExamplesScriptsContent', `Rendering ScriptEditorContentV2: category=${params.category}, name=${params.name}, script=${params.script}`);

    // 使用 ScriptEditorContentV2 显示脚本
    return (
        <Box>
            <ScriptEditorContentV2
                initialCategory={params.category}
                initialName={params.name}
                initialScript={params.script}
            />
        </Box>
    );
}
